import copy
import math


class VentilationMonitor:
    def __init__(self, temp_limit, moisture_limit):
        self._validate_number(temp_limit, "temp_limit")
        self._validate_number(moisture_limit, "moisture_limit")
        if not 0 <= moisture_limit <= 100:
            raise ValueError("moisture_limit must be between 0 and 100")
        self.temp_limit = temp_limit
        self.moisture_limit = moisture_limit
        self._fan_on = False
        self._history = []

    @staticmethod
    def _validate_number(value, name):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError(f"{name} must be numeric")
        if not math.isfinite(value):
            raise ValueError(f"{name} must be finite")

    @property
    def fan_on(self):
        return self._fan_on

    def observe(self, sample):
        if not isinstance(sample, dict):
            raise TypeError("sample must be a dictionary")
        if "temperature" not in sample or "humidity" not in sample:
            raise TypeError("sample requires temperature and humidity")
        temperature = sample["temperature"]
        humidity = sample["humidity"]
        self._validate_number(temperature, "temperature")
        self._validate_number(humidity, "humidity")
        if not 0 <= humidity <= 100:
            raise ValueError("humidity must be between 0 and 100")

        reasons = []
        if temperature >= self.temp_limit:
            reasons.append("temperature")
        if humidity > self.moisture_limit:
            reasons.append("humidity")
        fan_on = bool(reasons)
        result = {
            "sequence": len(self._history) + 1,
            "temperature": temperature,
            "humidity": humidity,
            "fan_on": fan_on,
            "reasons": tuple(reasons),
        }
        self._fan_on = fan_on
        self._history.append(copy.deepcopy(result))
        return copy.deepcopy(result)

    def history(self):
        return copy.deepcopy(self._history)

